import{_ as a,o as t,c as s,ao as o}from"./chunks/framework.DMEKwIGU.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md","lastUpdated":null}'),i={name:"troubleshooting.md"};function n(r,e,d,l,h,c){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="Troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#Troubleshooting" aria-label="Permalink to &quot;Troubleshooting {#Troubleshooting}&quot;">​</a></h1><h2 id="The-shared-library-is-not-found" tabindex="-1">The shared library is not found <a class="header-anchor" href="#The-shared-library-is-not-found" aria-label="Permalink to &quot;The shared library is not found {#The-shared-library-is-not-found}&quot;">​</a></h2><p>If <code>Colmat&#39;s BLAS library is missing</code> appears, build in the target Julia project and restart Julia.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Colmat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>If the build fails, check <code>deps/build.log</code> when using the repository. Also make sure that Git, Cargo, and the OS development tools are available.</p><h2 id="The-Rust-source-commit-does-not-match" tabindex="-1">The Rust source commit does not match <a class="header-anchor" href="#The-Rust-source-commit-does-not-match" aria-label="Permalink to &quot;The Rust source commit does not match {#The-Rust-source-commit-does-not-match}&quot;">​</a></h2><p>The build compares the actual checkout HEAD against <code>deps/upstream.toml</code>. The following commands only inspect the state.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deps/colmat-rs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rev-parse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HEAD</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deps/colmat-rs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --short</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deps/upstream.toml</span></span></code></pre></div><p>If there are local changes, save them and then prepare a clean checkout at the specified revision. For the procedure for an intentional dependency update, see <a href="/Colmat.jl/dev/development#Development">Development</a>.</p><h2 id="OpenBLAS-also-appears" tabindex="-1">OpenBLAS also appears <a class="header-anchor" href="#OpenBLAS-also-appears" aria-label="Permalink to &quot;OpenBLAS also appears {#OpenBLAS-also-appears}&quot;">​</a></h2><p>Multiple libraries appearing in <code>BLAS.get_config()</code> is expected because the forwarding targets for unsupported BLAS and LAPACK routines are retained. You can check the actual GEMM forwarding target with the method in <a href="/Colmat.jl/dev/getting-started#Getting-started">Getting started</a>. The display order of libraries alone does not tell you where each routine runs.</p><h2 id="Returning-after-another-backend-was-loaded" tabindex="-1">Returning after another backend was loaded <a class="header-anchor" href="#Returning-after-another-backend-was-loaded" aria-label="Permalink to &quot;Returning after another backend was loaded {#Returning-after-another-backend-was-loaded}&quot;">​</a></h2><p>Stop parallel computation, then call <code>Colmat.load_backend()</code>. <a href="/Colmat.jl/dev/manual/backend#Backends-and-fallbacks">Backends and fallbacks</a> explains the scope and ordering of switching.</p><h2 id="Thread-counts-do-not-match" tabindex="-1">Thread counts do not match <a class="header-anchor" href="#Thread-counts-do-not-match" aria-label="Permalink to &quot;Thread counts do not match {#Thread-counts-do-not-match}&quot;">​</a></h2><p><code>Colmat.get_num_threads()</code> returns Colmat&#39;s configuration value, while <code>BLAS.get_num_threads()</code> returns the value held by LBT. <code>Colmat.set_num_threads(n)</code> does not update the value recorded by LBT, so changing only Colmat can leave the two out of sync. To align every registered backend at once, use <code>BLAS.set_num_threads(n)</code>. See <a href="/Colmat.jl/dev/manual/threading#Thread-settings">Thread settings</a> for details.</p><h2 id="An-old-name-is-not-found" tabindex="-1">An old name is not found <a class="header-anchor" href="#An-old-name-is-not-found" aria-label="Permalink to &quot;An old name is not found {#An-old-name-is-not-found}&quot;">​</a></h2><p><code>FaerMatrix</code>, <code>FaerScratch</code>, <code>FaerTeam</code>, <code>with_resource</code>, and similar names were removed in 0.2. Use ordinary <code>Matrix</code> / <code>Vector</code> and <code>LinearAlgebra</code>. See <a href="/Colmat.jl/dev/migration#The-0.2-redesign">The 0.2 redesign</a> for the policy on the old API.</p>`,17)])])}const k=a(i,[["render",n]]);export{u as __pageData,k as default};
